def count_negatives(grid):
    """
    Count the total number of negative values in a 2D list (matrix).

    Args:
        grid: A 2D list of integers. May be empty or contain empty rows.

    Returns:
        The total count of negative integers in the matrix.
    """
    if not grid:
        return 0

    count = 0
    for row in grid:
        if not row:
            continue
        for value in row:
            if value < 0:
                count += 1
    return count
