def add_business_days(start_date_str, n):
    current = datetime.strptime(start_date_str, '%Y-%m-%d')
    if n == 0:
        return current.strftime('%Y-%m-%d')

    step = 1 if n > 0 else -1
    remaining = abs(n)

    while remaining > 0:
