def collapse_runs(s: str) -> str:
    if not s:
        return ""

    result = []
    i = 0
    n = len(s)

    while i < n:
        char = s[i]
        j = i + 1
        while j < n and s[j] == char:
            j += 1

        run_length = j - i
        if run_length >= 2:
            result.append(char + str(run_length))
        else:
            result.append(char)

        i = j

    return "".join(result)
