def count_reachable_components(n, edges, start):
    if not (0 <= start < n):
        return 0

    # Build adjacency list (ignore self-loops for connectivity purposes,
    # duplicates don't matter but harmless)
    adj = [[] for _ in range(n)]
    for u, v in edges:
        if u == v:
            continue
        adj[u].append(v)
        adj[v].append(u)

    # Step 1: Find all nodes reachable from start (BFS/DFS)
    reachable = set()
    stack = [start]
    reachable.add(start)
    while stack:
        node = stack.pop()
        for nbr in adj[node]:
            if nbr not in reachable:
                reachable.add(nbr)
                stack.append(nbr)

    # Step 2: Count connected components within the reachable subgraph
    visited = set()
    components = 0
    for node in reachable:
        if node in visited:
            continue
        components += 1
        # BFS/DFS restricted to reachable nodes
        stack = [node]
        visited.add(node)
        while stack:
            cur = stack.pop()
            for nbr in adj[cur]:
                if nbr in reachable and nbr not in visited:
                    visited.add(nbr)
                    stack.append(nbr)

    return components
```

