def closest_pair_sum(nums, target):
    if len(nums) < 2:
        return -1

    nums = sorted(nums)
    left, right = 0, len(nums) - 1
    best_diff = float('inf')

    while left < right:
        current_sum = nums[left] + nums[right]
        diff = abs(current_sum - target)

        if diff < best_diff:
            best_diff = diff

        if current_sum < target:
            left += 1
        elif current_sum > target:
            right -= 1
        else:
            return 0

    return best_diff
