def parse_log_blocks(text: str) -> list[dict]:
    blocks = []
    current = []

    def flush(block_lines):
        if not block_lines:
            return None
        headers = {}
        message_lines = []
        in_message = False
        for line in block_lines:
            stripped = line.strip()
            if not stripped:
                continue
            if not in_message and stripped.startswith("@"):
                rest = stripped[1:]
                parts = rest.split(None, 1)
                name = parts[0]
                value = parts[1].strip() if len(parts) > 1 else ""
                headers[name] = value
            else:
                in_message = True
                message_lines.append(line)
        # Remove surrounding blank lines from message
        while message_lines and not message_lines[0].strip():
            message_lines.pop(0)
        while message_lines and not message_lines[-1].strip():
            message_lines.pop()
        result = dict(headers)
        result["message"] = "\n".join(message_lines)
        return result

    for line in text.splitlines():
        if line.strip() == "---":
            parsed = flush(current)
            if parsed is not None:
                blocks.append(parsed)
            current = []
        else:
            current.append(line)

    parsed = flush(current)
    if parsed is not None:
        blocks.append(parsed)

    return blocks
